diff --git a/src/newest.js b/src/newest.js
+export function newest(items, limit) {
+  if (limit < 0) throw new RangeError('limit must be non-negative');
+  return items.slice(-(limit + 1));
+}
diff --git a/test/newest.test.js b/test/newest.test.js
+test('returns the newest two in original order', () => {
+  assert.deepEqual(newest(['a', 'b', 'c', 'd'], 2), ['c', 'd']);
+});
